function elodie_cms_ui(string $key): string
{
    $language = $GLOBALS['elodieCmsLanguage'] ?? 'fr';
    $languageTranslations = $GLOBALS['elodieCmsInterfaceTranslations'][$language]
        ?? $GLOBALS['elodieCmsInterfaceTranslations']['fr'];

    return $languageTranslations[$key]
        ?? $GLOBALS['elodieCmsInterfaceTranslations']['fr'][$key]
        ?? $key;
}
